def train(emails):
    spam = [set(t.lower().split()) for t, s in emails if s]
    ham = [set(t.lower().split()) for t, s in emails if not s]
    vocab = set().union(*spam, *ham)
    p_spam = len(spam) / len(emails)
    p_word_spam = {w: (sum(w in e for e in spam) + 1) / (len(spam) + 2) for w in vocab}
    p_word_ham = {w: (sum(w in e for e in ham) + 1) / (len(ham) + 2) for w in vocab}
    return p_spam, p_word_spam, p_word_ham

def spam_probability(text, p_spam, p_word_spam, p_word_ham):
    spam_score = math.log(p_spam)
    ham_score = math.log(1 - p_spam)
    for w in set(text.lower().split()):
        if w in p_word_spam:
            spam_score += math.log(p_word_spam[w])
            ham_score += math.log(p_word_ham[w])
    return 1 / (1 + math.exp(ham_score - spam_score))

def bayes(prior, like_if_true, like_if_false):
    top = prior * like_if_true
    return top / (top + (1 - prior) * like_if_false)

